public class PriorWorkDeskTest {
 private final Map<Integer,String> memory=new HashMap<Integer,String>();private int calls,reads,writes;private boolean enabled=true,unavailable=false;
 private OutputAuditJournal journal;private EnterpriseDispatcher dispatcher;private CacheAuthority cache;
 @Before public void convene(){journal=JvmAuditJournalFactory.create(new EphemeralAuditStore());final OutputTransactionCoordinator transactions=new OutputTransactionCoordinator(journal);final SlopFizzBuzz production=ExplicitEnterpriseAssembly.assemble(transactions);
  cache=new CacheAuthority(new CacheRepository(){public boolean enabled(){return enabled;}public String get(int n){reads++;if(unavailable)throw new IllegalStateException("closed");return memory.get(n);}public void put(int n,String body,int ttl){assertEquals(86400,ttl);writes++;memory.put(n,body);}});
  dispatcher=new EnterpriseDispatcher(new SlopFizzBuzz(){public void slopFizzBuzz(int limit){calls++;production.slopFizzBuzz(limit);}},transactions,journal,cache,new ReleaseCustodyReport("unknown",0));
 }
 @Test public void ratifiedReuseAddsNeitherNumericalAuditNorFreshProduction()throws Exception{EnterpriseExchange first=dispatcher.dispatch("GET","/fizzbuzz?limit=15");String digest=journal.snapshot().get(14).getDigest();EnterpriseExchange hit=dispatcher.dispatch("GET","/fizzbuzz/explained?limit=15");assertEquals(200,hit.status);assertEquals("HIT",hit.headers.get("X-SlopBuzz-Cache"));assertEquals("CACHE_REUSED",hit.headers.get("X-SlopBuzz-Onboarding-State"));assertNull(hit.headers.get("X-SlopBuzz-Onboarding-Trace"));assertTrue(hit.headers.get("X-SlopBuzz-Precedent-Trace").contains("Certificate of Authorized Non-Performance"));assertTrue(hit.text().contains("\"precedent\":{\"schema\":\"slopbuzz-precedent/v1\""));assertEquals(1,calls);assertEquals(15,journal.snapshot().size());assertEquals(digest,journal.snapshot().get(14).getDigest());assertEquals(1,writes);assertEquals(EveryPriorWorkPetitionTest.oracle(15),first.text());}
 @Test public void aPoisonedCacheBecomesAMissAndIsReplacedByExactlyOneFreshMandate()throws Exception{memory.put(15,EveryPriorWorkPetitionTest.oracle(15).replace("Fizz","fizz"));EnterpriseExchange result=dispatcher.dispatch("GET","/fizzbuzz/explained?limit=15");assertEquals(200,result.status);assertEquals("MISS",result.headers.get("X-SlopBuzz-Cache"));assertTrue(result.headers.get("X-SlopBuzz-Precedent-Trace").contains("\"status\":\"REJECTED\""));assertTrue(result.text().contains("Independent Lexical Bench"));assertEquals(1,calls);assertEquals(15,journal.snapshot().size());assertEquals(1,writes);assertEquals(EveryPriorWorkPetitionTest.oracle(15),memory.get(15));assertTrue(cache.statusJson().contains("\"rejectedPrecedents\":1"));dispatcher.dispatch("GET","/fizzbuzz?limit=15");assertEquals(1,calls);assertEquals(15,journal.snapshot().size());}
 @Test public void rawLegacyEntriesNeedNoMigrationAndZeroStillGetsALicense()throws Exception{memory.put(0,"");EnterpriseExchange zero=dispatcher.dispatch("GET","/fizzbuzz?limit=0");assertEquals(200,zero.status);assertEquals("",zero.text());assertEquals("HIT",zero.headers.get("X-SlopBuzz-Cache"));assertTrue(zero.headers.get("X-SlopBuzz-Precedent-Trace").contains("\"certifiedLines\":0"));assertEquals(0,calls);assertEquals(0,writes);assertTrue(journal.snapshot().isEmpty());}
 @Test public void disabledAndUnavailableRepositoriesCannotPretendToHaveAReuseLicense()throws Exception{enabled=false;EnterpriseExchange disabled=dispatcher.dispatch("GET","/fizzbuzz?limit=1");assertEquals("BYPASS",disabled.headers.get("X-SlopBuzz-Cache"));assertNull(disabled.headers.get("X-SlopBuzz-Precedent-Trace"));assertEquals(0,reads);enabled=true;unavailable=true;EnterpriseExchange failed=dispatcher.dispatch("GET","/fizzbuzz?limit=1");assertEquals("BYPASS",failed.headers.get("X-SlopBuzz-Cache"));assertNull(failed.headers.get("X-SlopBuzz-Precedent-Trace"));assertEquals(2,calls);assertEquals(2,journal.snapshot().size());}
 @Test public void rehearsalsDoNotConsultTheRealRepositoryOrChangeAnyNumericalEvidence()throws Exception{String before=cache.statusJson();for(String scenario:new String[]{"approved","zero","wrong-mandate","missing-line","lowercase-fizz"}){EnterpriseExchange result=dispatcher.dispatch("GET","/precedent/rehearsal?scenario="+scenario);assertEquals(200,result.status);assertEquals("READ_ONLY_REHEARSAL",result.headers.get("X-SlopBuzz-Proceedings"));assertEquals("no-store",result.headers.get("Cache-Control"));assertTrue(result.text().contains("\"purpose\":\"REHEARSAL\""));}assertEquals(before,cache.statusJson());assertEquals(0,reads);assertEquals(0,writes);assertEquals(0,calls);assertTrue(journal.snapshot().isEmpty());}
 @Test public void onlyAnExactUnambiguousRehearsalQueryIsAdmitted()throws Exception{assertEquals(200,dispatcher.dispatch("GET","/precedent/rehearsal").status);for(String query:new String[]{"","scenario=","scenario=other","scenario=approved&x=1","scenario=zero&scenario=approved","scenario=%7Aero","x=zero"})assertEquals(query,400,dispatcher.dispatch("GET","/precedent/rehearsal?"+query).status);for(String method:new String[]{"POST","PUT","PATCH","DELETE","HEAD","OPTIONS"}){EnterpriseExchange result=dispatcher.dispatch(method,"/precedent/rehearsal");assertEquals(405,result.status);assertEquals("GET",result.headers.get("Allow"));}assertEquals(404,dispatcher.dispatch("GET","/precedent/rehearsal/child").status);assertEquals(0,reads);}
 @Test public void transientMagnitudeWindowsDoNotConveneACacheCourt()throws Exception{EnterpriseExchange result=dispatcher.dispatch("GET","/fizzbuzz/window/explained?start=9007199254740993&count=3");assertEquals(200,result.status);assertFalse(result.text().contains("PRECEDENT_APPROVED"));assertNull(result.headers.get("X-SlopBuzz-Precedent-Trace"));assertTrue(journal.snapshot().isEmpty());assertEquals(0,reads);}
}
